# Looking at the task description recall, it mentioned "swapper" logic
# Let me try a color swap transformation on the input grid

input_6 = [
    [5, 8, 7, 8, 5, 5],
    [8, 8, 7, 4, 8, 8],
    [5, 4, 8, 4, 8, 5],
    [8, 7, 8, 8, 8, 8],
    [8, 8, 8, 8, 5, 5],
    [8, 5, 5, 8, 5, 5]
]

# Hypothesis 1: Swap 4 <-> 7, 5 <-> 8 (classic reciprocal swap)
def swap_colors_47_58(grid):
    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == 4:
                new_row.append(7)
            elif cell == 7:
                new_row.append(4)
            elif cell == 5:
                new_row.append(8)
            elif cell == 8:
                new_row.append(5)
            else:
                new_row.append(cell)
        result.append(new_row)
    return result

# Hypothesis 2: Swap 4 <-> 7 only
def swap_colors_47(grid):
    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == 4:
                new_row.append(7)
            elif cell == 7:
                new_row.append(4)
            else:
                new_row.append(cell)
        result.append(new_row)
    return result

# Hypothesis 3: Swap 5 <-> 8 only
def swap_colors_58(grid):
    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == 5:
                new_row.append(8)
            elif cell == 8:
                new_row.append(5)
            else:
                new_row.append(cell)
        result.append(new_row)
    return result

# Print candidates
print("Hypothesis 1 (4<->7, 5<->8):")
print(swap_colors_47_58(input_6))

print("\nHypothesis 2 (4<->7 only):")
print(swap_colors_47(input_6))

print("\nHypothesis 3 (5<->8 only):")
print(swap_colors_58(input_6))

